INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-MASTECTOMIA_RECONSTRUCAO_IMEDIATA-001-C01','MAMA-MASTECTOMIA_RECONSTRUCAO_IMEDIATA-001',1,'Para que serve este documento','Este material ajuda você e sua família a se prepararem, reconhecerem o que costuma acontecer e saberem quando pedir ajuda. Ele complementa — e não substitui — as instruções individualizadas da equipe.','educativo','{"cancer_type": "mama", "care_phase": "cirurgia", "procedure_slug": "mastectomia-reconstrucao-imediata", "reading_level": "linguagem_simples", "simulated": true, "section": "Para que serve este documento"}'::jsonb) ON CONFLICT DO NOTHING;
