INSERT INTO content.documents(document_id,title,document_type,cancer_type,care_phase,procedure_slug,responsible_physician,version,created_at,last_reviewed_at,next_review_at,patient_markdown_path,metadata) VALUES ('MAMA-SEROMA_FERIDA-001','Seroma e cuidados com a ferida da mama','orientacao_clinica','mama','pos_operatorio','seroma-ferida','Dra. Fulana Silva','0.1.0','2026-08-08','2026-08-08','2027-02-08','documents/clinical/mama/seroma-ferida.md','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C01','MAMA-SEROMA_FERIDA-001',1,'Para que serve este documento','Este material ajuda você e sua família a se prepararem, reconhecerem o que costuma acontecer e saberem quando pedir ajuda. Ele complementa — e não substitui — as instruções individualizadas da equipe.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Para que serve este documento"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C02','MAMA-SEROMA_FERIDA-001',2,'Orientação específica','Uma bolsa de líquido pode formar abaulamento e sensação de movimento. Não tente furar ou esvaziar em casa; a equipe decidirá se precisa drenar.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Orientação específica"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C03','MAMA-SEROMA_FERIDA-001',3,'Antes do procedimento ou sessão','Confirme data, local, jejum e medicamentos diretamente com a equipe. Leve documento, lista atualizada de remédios, alergias, exames solicitados e contato de quem o acompanhará. Não suspenda anticoagulantes, remédios para diabetes, pressão ou suplementos por conta própria. Avise sobre febre, tosse nova, infecção, gravidez possível, queda recente, dificuldade de locomoção ou mudança importante no estado de saúde.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Antes do procedimento ou sessão"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C04','MAMA-SEROMA_FERIDA-001',4,'Ao chegar em casa','Use somente os medicamentos prescritos e respeite os horários. Organize água, alimentos tolerados, termômetro e telefones de contato. Nas primeiras horas, tenha um adulto disponível quando houver sedação ou limitação de movimento. Levante devagar e caminhe apenas quando for seguro. Não dirija enquanto estiver com dor limitante, sonolência ou usando medicamento que reduza a atenção.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Ao chegar em casa"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C05','MAMA-SEROMA_FERIDA-001',5,'Cuidados práticos','Mantenha curativos limpos e secos pelo tempo orientado. Não aplique álcool, água oxigenada, pomadas, ervas, óleos ou receitas caseiras. Banho, exercícios, alimentação e retorno ao trabalho variam conforme o tratamento; prevalece a orientação recebida na alta. Anote sintomas, temperatura, evacuações, volume de drenos ou estomia quando solicitado.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Cuidados práticos"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C06','MAMA-SEROMA_FERIDA-001',6,'O que pode acontecer','Cansaço, desconforto controlável, mudança de apetite, sono e funcionamento do intestino podem ocorrer. O esperado é haver estabilidade ou melhora gradual. Compare o sintoma com o seu próprio dia anterior, não com a experiência de outra pessoa. Se algo o preocupa, entre em contato mesmo que não apareça nesta lista.','educativo','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "O que pode acontecer"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C07','MAMA-SEROMA_FERIDA-001',7,'Quando falar com a equipe no mesmo dia','Entre em contato no mesmo dia se houver febre conforme o limite fornecido pela equipe, dor que não melhora com a prescrição, vômitos repetidos, diarreia relevante, redução da urina, ferida mais vermelha ou quente, secreção, sangramento persistente, dificuldade para usar medicamentos ou piora em vez de melhora. Ramal 0000 (simulação).','contato_no_mesmo_dia','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando falar com a equipe no mesmo dia"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEROMA_FERIDA-001-C08','MAMA-SEROMA_FERIDA-001',8,'Quando procurar emergência','Procure o serviço de emergência mais próximo se houver falta de ar importante, desmaio, confusão, dor forte no peito, sangramento volumoso, convulsão, reação alérgica com inchaço de rosto ou garganta, fraqueza súbita, incapacidade de acordar normalmente ou piora rápida. Não espere resposta do chatbot e não atravesse a cidade se houver um serviço mais próximo.','emergencia','{"cancer_type": "mama", "care_phase": "pos_operatorio", "procedure_slug": "seroma-ferida", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando procurar emergência"}'::jsonb) ON CONFLICT DO NOTHING;
