INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C01','MAMA-RESSONANCIA_CONTRASTE-001',1,'Para que serve este documento','Este material ajuda você e sua família a se prepararem, reconhecerem o que costuma acontecer e saberem quando pedir ajuda. Ele complementa — e não substitui — as instruções individualizadas da equipe.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Para que serve este documento"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C02','MAMA-RESSONANCIA_CONTRASTE-001',2,'Orientação específica','Informe gravidez possível, implantes, dispositivos, alergias e doença renal. Retire objetos metálicos conforme orientação do serviço.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Orientação específica"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C03','MAMA-RESSONANCIA_CONTRASTE-001',3,'Antes do procedimento ou sessão','Confirme data, local, jejum e medicamentos diretamente com a equipe. Leve documento, lista atualizada de remédios, alergias, exames solicitados e contato de quem o acompanhará. Não suspenda anticoagulantes, remédios para diabetes, pressão ou suplementos por conta própria. Avise sobre febre, tosse nova, infecção, gravidez possível, queda recente, dificuldade de locomoção ou mudança importante no estado de saúde.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Antes do procedimento ou sessão"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C04','MAMA-RESSONANCIA_CONTRASTE-001',4,'Ao chegar em casa','Use somente os medicamentos prescritos e respeite os horários. Organize água, alimentos tolerados, termômetro e telefones de contato. Nas primeiras horas, tenha um adulto disponível quando houver sedação ou limitação de movimento. Levante devagar e caminhe apenas quando for seguro. Não dirija enquanto estiver com dor limitante, sonolência ou usando medicamento que reduza a atenção.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Ao chegar em casa"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C05','MAMA-RESSONANCIA_CONTRASTE-001',5,'Cuidados práticos','Mantenha curativos limpos e secos pelo tempo orientado. Não aplique álcool, água oxigenada, pomadas, ervas, óleos ou receitas caseiras. Banho, exercícios, alimentação e retorno ao trabalho variam conforme o tratamento; prevalece a orientação recebida na alta. Anote sintomas, temperatura, evacuações, volume de drenos ou estomia quando solicitado.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Cuidados práticos"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C06','MAMA-RESSONANCIA_CONTRASTE-001',6,'O que pode acontecer','Cansaço, desconforto controlável, mudança de apetite, sono e funcionamento do intestino podem ocorrer. O esperado é haver estabilidade ou melhora gradual. Compare o sintoma com o seu próprio dia anterior, não com a experiência de outra pessoa. Se algo o preocupa, entre em contato mesmo que não apareça nesta lista.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "O que pode acontecer"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C07','MAMA-RESSONANCIA_CONTRASTE-001',7,'Quando falar com a equipe no mesmo dia','Entre em contato no mesmo dia se houver febre conforme o limite fornecido pela equipe, dor que não melhora com a prescrição, vômitos repetidos, diarreia relevante, redução da urina, ferida mais vermelha ou quente, secreção, sangramento persistente, dificuldade para usar medicamentos ou piora em vez de melhora. Ramal 0000 (simulação).','contato_no_mesmo_dia','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando falar com a equipe no mesmo dia"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C08','MAMA-RESSONANCIA_CONTRASTE-001',8,'Quando procurar emergência','Procure o serviço de emergência mais próximo se houver falta de ar importante, desmaio, confusão, dor forte no peito, sangramento volumoso, convulsão, reação alérgica com inchaço de rosto ou garganta, fraqueza súbita, incapacidade de acordar normalmente ou piora rápida. Não espere resposta do chatbot e não atravesse a cidade se houver um serviço mais próximo.','emergencia','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando procurar emergência"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C09','MAMA-RESSONANCIA_CONTRASTE-001',9,'Alertas para situações especiais','Pessoas idosas ou frágeis podem desidratar e perder autonomia rapidamente. Gestantes ou quem possa estar grávida devem avisar antes de exames e medicamentos. Pessoas com deficiência devem solicitar acessibilidade, acompanhante e instruções no formato adequado. Quem mora sozinho deve combinar uma rede de apoio e um plano para emergências.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Alertas para situações especiais"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-RESSONANCIA_CONTRASTE-001-C10','MAMA-RESSONANCIA_CONTRASTE-001',10,'Perguntas para a próxima consulta','Pergunte qual é o objetivo do tratamento, quais restrições valem para você, quando revisar a ferida ou exames, como receber o resultado, quais sintomas mudam o plano e quem contatar fora do horário. Leve suas anotações e peça que a equipe registre orientações diferentes deste material.','educativo','{"cancer_type": "mama", "care_phase": "imagem", "procedure_slug": "ressonancia-contraste", "reading_level": "linguagem_simples", "simulated": true, "section": "Perguntas para a próxima consulta"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.documents(document_id,title,document_type,cancer_type,care_phase,procedure_slug,responsible_physician,version,created_at,last_reviewed_at,next_review_at,patient_markdown_path,metadata) VALUES ('MAMA-SEXUALIDADE-001','Sexualidade após tratamento do câncer de mama','orientacao_clinica','mama','qualidade_de_vida','sexualidade','Dra. Fulana Silva','0.1.0','2026-08-08','2026-08-08','2027-02-08','documents/clinical/mama/sexualidade.md','{"cancer_type": "mama", "care_phase": "qualidade_de_vida", "procedure_slug": "sexualidade", "reading_level": "linguagem_simples", "simulated": true}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('MAMA-SEXUALIDADE-001-C01','MAMA-SEXUALIDADE-001',1,'Para que serve este documento','Este material ajuda você e sua família a se prepararem, reconhecerem o que costuma acontecer e saberem quando pedir ajuda. Ele complementa — e não substitui — as instruções individualizadas da equipe.','educativo','{"cancer_type": "mama", "care_phase": "qualidade_de_vida", "procedure_slug": "sexualidade", "reading_level": "linguagem_simples", "simulated": true, "section": "Para que serve este documento"}'::jsonb) ON CONFLICT DO NOTHING;
