INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C02','COLORRETAL-CAPECITABINA-001',2,'Orientação específica','Tome exatamente como prescrito, sem triturar ou compensar dose. Guarde longe de crianças e não compartilhe comprimidos.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Orientação específica"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C03','COLORRETAL-CAPECITABINA-001',3,'Antes do procedimento ou sessão','Confirme data, local, jejum e medicamentos diretamente com a equipe. Leve documento, lista atualizada de remédios, alergias, exames solicitados e contato de quem o acompanhará. Não suspenda anticoagulantes, remédios para diabetes, pressão ou suplementos por conta própria. Avise sobre febre, tosse nova, infecção, gravidez possível, queda recente, dificuldade de locomoção ou mudança importante no estado de saúde.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Antes do procedimento ou sessão"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C04','COLORRETAL-CAPECITABINA-001',4,'Ao chegar em casa','Use somente os medicamentos prescritos e respeite os horários. Organize água, alimentos tolerados, termômetro e telefones de contato. Nas primeiras horas, tenha um adulto disponível quando houver sedação ou limitação de movimento. Levante devagar e caminhe apenas quando for seguro. Não dirija enquanto estiver com dor limitante, sonolência ou usando medicamento que reduza a atenção.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Ao chegar em casa"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C05','COLORRETAL-CAPECITABINA-001',5,'Cuidados práticos','Mantenha curativos limpos e secos pelo tempo orientado. Não aplique álcool, água oxigenada, pomadas, ervas, óleos ou receitas caseiras. Banho, exercícios, alimentação e retorno ao trabalho variam conforme o tratamento; prevalece a orientação recebida na alta. Anote sintomas, temperatura, evacuações, volume de drenos ou estomia quando solicitado.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Cuidados práticos"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C06','COLORRETAL-CAPECITABINA-001',6,'O que pode acontecer','Cansaço, desconforto controlável, mudança de apetite, sono e funcionamento do intestino podem ocorrer. O esperado é haver estabilidade ou melhora gradual. Compare o sintoma com o seu próprio dia anterior, não com a experiência de outra pessoa. Se algo o preocupa, entre em contato mesmo que não apareça nesta lista.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "O que pode acontecer"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C07','COLORRETAL-CAPECITABINA-001',7,'Quando falar com a equipe no mesmo dia','Entre em contato no mesmo dia se houver febre conforme o limite fornecido pela equipe, dor que não melhora com a prescrição, vômitos repetidos, diarreia relevante, redução da urina, ferida mais vermelha ou quente, secreção, sangramento persistente, dificuldade para usar medicamentos ou piora em vez de melhora. Ramal 0000 (simulação).','contato_no_mesmo_dia','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando falar com a equipe no mesmo dia"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C08','COLORRETAL-CAPECITABINA-001',8,'Quando procurar emergência','Procure o serviço de emergência mais próximo se houver falta de ar importante, desmaio, confusão, dor forte no peito, sangramento volumoso, convulsão, reação alérgica com inchaço de rosto ou garganta, fraqueza súbita, incapacidade de acordar normalmente ou piora rápida. Não espere resposta do chatbot e não atravesse a cidade se houver um serviço mais próximo.','emergencia','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Quando procurar emergência"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C09','COLORRETAL-CAPECITABINA-001',9,'Alertas para situações especiais','Pessoas idosas ou frágeis podem desidratar e perder autonomia rapidamente. Gestantes ou quem possa estar grávida devem avisar antes de exames e medicamentos. Pessoas com deficiência devem solicitar acessibilidade, acompanhante e instruções no formato adequado. Quem mora sozinho deve combinar uma rede de apoio e um plano para emergências.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Alertas para situações especiais"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO content.chunks(chunk_id,parent_document_id,ordinal,heading,content_markdown,urgency,metadata) VALUES ('COLORRETAL-CAPECITABINA-001-C10','COLORRETAL-CAPECITABINA-001',10,'Perguntas para a próxima consulta','Pergunte qual é o objetivo do tratamento, quais restrições valem para você, quando revisar a ferida ou exames, como receber o resultado, quais sintomas mudam o plano e quem contatar fora do horário. Leve suas anotações e peça que a equipe registre orientações diferentes deste material.','educativo','{"cancer_type": "colorretal", "care_phase": "quimioterapia", "procedure_slug": "capecitabina", "reading_level": "linguagem_simples", "simulated": true, "section": "Perguntas para a próxima consulta"}'::jsonb) ON CONFLICT DO NOTHING;
